import{_ as n}from"./chunks/image12.BRgDBKom.js";import{_ as i,o as a,c as o,am as r}from"./chunks/framework.CenUaW7a.js";const s="/projects/AiMechaM1/en/advanced-kit/assets/image1.DDNPx9-4.webp",t="/projects/AiMechaM1/en/advanced-kit/assets/image2.DYU1t2Mw.png",l="/projects/AiMechaM1/en/advanced-kit/assets/image3.CTmDh9Vd.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image4.D9KyE8s0.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image5.b3To3bkz.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image6.DfAgWEUm.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image7.CG6Izr4E.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image8.DvgkMA8l.png",k=JSON.parse('{"title":"3.23 Lesson 23: License Plate Recognition","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.23 Lesson 23 License Plate Recognition.md","filePath":"docs/3. Course materials/3.23 Lesson 23 License Plate Recognition.md"}'),m={name:"docs/3. Course materials/3.23 Lesson 23 License Plate Recognition.md"};function u(f,e,y,b,w,v){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-23-lesson-23-license-plate-recognition" tabindex="-1">3.23 Lesson 23: License Plate Recognition <a class="header-anchor" href="#_3-23-lesson-23-license-plate-recognition" aria-label="Permalink to &quot;3.23 Lesson 23: License Plate Recognition&quot;">​</a></h1><h2 id="_3-23-1-lesson-introduction" tabindex="-1">3.23.1 Lesson Introduction <a class="header-anchor" href="#_3-23-1-lesson-introduction" aria-label="Permalink to &quot;3.23.1 Lesson Introduction&quot;">​</a></h2><p>Focusing on K230 license plate recognition, this lesson introduces optical character recognition, abbreviated as OCR. Taking inspiration from electronic toll collection, smart access control, and contactless passage, this lesson demonstrates how license plate recognition improves daily efficiency. This section covers the OCR workflow: image input, text region detection, character segmentation and matching, and text output. Through a hands-on unmanned parking lot project where the car acts as a barrier gate, illuminating a green light and moving aside when a license plate is recognized, and illuminating a yellow light to stand by when none is recognized, this lesson introduces text-output visual results for the first time, demonstrating how to retrieve text for decision-making and bridging the gap between images and semantic meaning. Establishing a general understanding of OCR lays the foundation for document digitization and related applications.</p><h2 id="_3-23-2-learning-objectives" tabindex="-1">3.23.2 Learning Objectives <a class="header-anchor" href="#_3-23-2-learning-objectives" aria-label="Permalink to &quot;3.23.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the definition and basic principles of optical character recognition. Master the technical workflow of license plate recognition, and learn key technical stages including text region detection, character segmentation, and template matching.</p><p><strong>2.</strong> Launch the license plate recognition mode on the K230 module and verify its functionality. Proficiently master programming commands related to license plate recognition and read the recognized license plate text content.</p><p><strong>3.</strong> Establish procedural technical thinking to understand the step-by-step decomposition of complex recognition tasks. Cultivate systems thinking to translate visual recognition into automated control logic.</p><p><strong>4.</strong> Connect highway electronic toll collection, residential barrier gates, parking lot contactless payment, traffic violation capture, and campus vehicle management to real-world application scenarios, understanding the broad value of license plate recognition technology in intelligent transportation and smart cities.</p><h2 id="_3-23-3-preparation" tabindex="-1">3.23.3 Preparation <a class="header-anchor" href="#_3-23-3-preparation" aria-label="Permalink to &quot;3.23.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-Wheel Car Advanced Kit</p></li><li><p>Type-C data cable</p></li><li><p>Computer × 1</p></li><li><p>Remote controller</p></li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>OCR Principle Description</strong>:</p><ul><li><p><strong>Definition</strong>: Optical Character Recognition, abbreviated as OCR, is a technology that converts text within images into editable text.</p></li><li><p><strong>Workflow</strong>: Image input → text region detection → character segmentation → character matching → text output.</p></li><li><p><strong>Core</strong>: Translating image pixels into semantic text information so that machines can &quot;read and interpret&quot; image content.</p></li></ul><p><strong>License Plate Recognition Technical Workflow</strong>:</p><ul><li><p>Step 1: <strong>License Plate Localization</strong>: Locate the license plate region within the frame using color characteristics such as a blue background with white characters or a yellow background with black characters, alongside rectangular contour features.</p></li><li><p>Step 2: <strong>Character Segmentation</strong>: Segment individual characters within the license plate region one by one to prepare them for standalone recognition.</p></li><li><p>Step 3: <strong>Character Recognition</strong>: Recognize each character using OCR technology and assemble them into a complete license plate number.</p></li><li><p>Step 4: <strong>Result Output</strong>: Output the license plate text, four-corner coordinates, and other information.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li><p>Connect the K230 screen module to <strong>port A</strong> of the controller.</p></li><li><p>Connect the RGB LEDs to the corresponding lighting effect ports.</p></li><li><p>Connect the ultrasonic sensor to <strong>port K</strong>.</p></li></ul><p><strong>Menu Navigation Path</strong>:</p><ul><li>Recognition Mode → Image Recognition → License Plate Recognition.</li></ul><p><strong>Factors Influencing Recognition Performance</strong>:</p><ul><li><p>Face the license plate directly toward the camera for optimal results, as excessive tilt angles reduce the recognition rate.</p></li><li><p>Ensure uniform and sufficient lighting, as glare or backlighting reduces recognition accuracy.</p></li><li><p>Keep the license plate at a moderate size within the frame, as being too large or too small compromises performance.</p></li><li><p>Ensure the license plate is clear, intact, and unobstructed, as partial occlusion may cause recognition failure.</p></li></ul><h2 id="_3-23-4-hands-on-project" tabindex="-1">3.23.4 Hands-On Project <a class="header-anchor" href="#_3-23-4-hands-on-project" aria-label="Permalink to &quot;3.23.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This project simulates an unmanned smart parking lot barrier gate, centered around visual recognition triggering automated gate control. The K230 captures the frame, and the license plate algorithm locates, segments, and processes OCR to output text and coordinates. The decision-making layer checks for the presence of a license plate, granting passage when present and standing by when absent. The execution layer illuminates green lights while driving the car right by 20 cm at 60 rpm to simulate lifting the gate, or illuminates yellow lights on standby when no license plate is present. The system simulates the complete workflow of vehicle entry → recognition → gate lifting → passage, illustrating a typical application of vision-driven automated decision-making.</p><img loading="lazy" height="540" width="960" src="'+s+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="625" width="428" src="'+t+'" class="common_img" style="width:460px;aspect-ratio:428 / 625;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Presence detection</td><td style="text-align:center;"><img loading="lazy" height="53" width="345" src="'+l+'" class="common_img" style="width:400px;aspect-ratio:345 / 53;"></td><td style="text-align:left;">Determines whether a license plate is present in the current frame and returns a boolean value.</td></tr><tr><td style="text-align:center;">Quantity counting</td><td style="text-align:center;"><img loading="lazy" height="54" width="406" src="'+c+'" class="common_img" style="width:400px;aspect-ratio:406 / 54;"></td><td style="text-align:left;">Counts the number of license plates detected in the frame, supporting multi-plate scenarios.</td></tr><tr><td style="text-align:center;">Text retrieval</td><td style="text-align:center;"><img loading="lazy" height="54" width="614" src="'+p+'" class="common_img" style="width:400px;aspect-ratio:614 / 54;"></td><td style="text-align:left;">Reads the recognized license plate number text content, such as <code>HU A12345</code>.</td></tr><tr><td style="text-align:center;">Coordinate parameters</td><td style="text-align:center;"><img loading="lazy" height="305" width="638" src="'+g+'" class="common_img" style="width:400px;aspect-ratio:638 / 305;"></td><td style="text-align:left;">Reads the four-corner coordinate values of the license plate, including top-left, top-right, bottom-right, and bottom-left, for positional evaluation.</td></tr><tr><td style="text-align:center;">Light control</td><td style="text-align:center;"><img loading="lazy" height="78" width="454" src="'+d+'" class="common_img" style="width:400px;aspect-ratio:454 / 78;"></td><td style="text-align:left;">Controls indicator light colors to simulate red, green, and yellow status signals of a barrier gate.</td></tr><tr><td style="text-align:center;">Motion control</td><td style="text-align:center;"><img loading="lazy" height="61" width="548" src="'+h+'" class="common_img" style="width:400px;aspect-ratio:548 / 61;"></td><td style="text-align:left;">Precisely controls the translational movement distance of the car to simulate lifting the barrier gate to clear the path.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task: Unmanned Parking Lot: Recognizing License Plates and Opening Gates Automatically</strong></p><ul><li><p>Initialization settings: At startup, initialize port A, set the running mode to license plate recognition, start detection, set all ultrasonic sensor RGB lights to red, and set the onboard RGB LEDs to red to represent the initial standby status.</p></li><li><p>Main loop structure: Execute <code>Update and save result data</code> as the first step inside the repeat forever loop to synchronize the latest license plate recognition data.</p></li><li><p>Dual-branch condition: Use an if-else structure to evaluate the condition <code>Is license plate detected?</code>.</p></li><li><p>Passage branch upon detecting a license plate: Set the onboard RGB LED color to green, set all ultrasonic sensor RGB lights to green, and drive the Mecanum-wheel car right by 20 cm at 60 rpm to simulate the barrier gate lifting laterally to clear the path.</p></li><li><p>Standby branch when no license plate is detected: Set all ultrasonic sensor RGB lights to yellow, and set the onboard RGB LED color to yellow to represent the waiting status.</p></li><li><p>Looped execution: The main loop monitors continuously, returning automatically to the yellow standby status once the license plate leaves and opening the gate automatically when a plate reappears.</p></li></ul><img loading="lazy" height="625" width="428" src="'+t+'" class="common_img" style="width:460px;aspect-ratio:428 / 625;"><p><strong>Program Design Key Points</strong></p><ul><li><p>Real-time updates: Update data before evaluating conditions in every loop cycle to ensure the program uses the latest recognition results.</p></li><li><p>Status feedback: Provide intuitive system status feedback via different light colors, red for initial state, yellow for waiting, and green for passage, matching traffic signal conventions.</p></li><li><p>Translation distance: Adjust the 20 cm rightward translation distance according to the physical setup to ensure sufficient clearance for the simulated barrier gate.</p></li><li><p>Movement rotational speed: Set the speed to 60 rpm for a moderate pace that is neither too slow nor too fast to maintain stability.</p></li></ul><p><strong>Advanced Functional Expansion Ideas</strong></p><ul><li><p>Whitelist mechanism: Retrieve license plate text and compare it against a preset whitelist, opening the gate only for authorized vehicles and sounding an alarm for unfamiliar plates.</p></li><li><p>Billing by duration: Record the initial appearance and departure timestamps of a license plate to calculate parking duration and fees automatically.</p></li><li><p>Multi-plate priority: When multiple license plates appear in the frame, select the largest or most centrally located plate as the primary target.</p></li><li><p>Voice announcements: Play prompt tones on the buzzer or announce license plate numbers via voice upon recognizing a plate.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/License Plate Number Recognition</a>.</strong></p></div></li></ul><p><strong>Program Upload:</strong></p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to upload the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-23-5-expansion-and-advancement" tabindex="-1">3.23.5 Expansion and Advancement <a class="header-anchor" href="#_3-23-5-expansion-and-advancement" aria-label="Permalink to &quot;3.23.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Intelligent License Plate Whitelist Access Control System</strong></p><p>Design a license plate whitelist management system pre-configured with three authorized license plate numbers. Upon recognizing a plate, retrieve the text content and compare it against the whitelist, illuminating green lights and opening the gate for authorized vehicles while illuminating red lights and sounding a buzzer alarm for unfamiliar vehicles. Simulate a real residential community or industrial park access control system to understand the progression of license plate recognition from &quot;presence detection&quot; to &quot;identity verification&quot;.</p><p><strong>Expansion Project 2: Parking Lot Timed Billing System</strong></p><p>Incorporate timer variables to record vehicle entry and exit timestamps to calculate parking duration automatically. Design a tiered billing logic: free within 15 minutes, 5 currency units within the first hour, and 3 currency units per hour thereafter. Begin timing when a license plate enters and settle and display charges upon recognizing the same plate exiting. Simulate the contactless payment workflow of a real parking lot to understand how visual recognition drives a complete commercial loop in smart parking.</p><h2 id="_3-23-6-q-a" tabindex="-1">3.23.6 Q&amp;A <a class="header-anchor" href="#_3-23-6-q-a" aria-label="Permalink to &quot;3.23.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What is the operating principle of OCR text recognition?</strong></p><p><strong>Answer</strong>: The core of optical character recognition is <strong>image feature matching</strong>, which compares the shapes of characters in an image one by one against known character templates to identify the closest match.</p><p><strong>Q2: The first step of license plate recognition is license plate localization, which involves finding where the license plate is within the frame. How does the machine accurately locate the license plate amidst a complex background?</strong></p><p><strong>Answer</strong>: Localization relies on a joint combination of <strong>color features + shape contours + texture patterns</strong>.</p><h2 id="_3-23-7-technical-support-and-discussion" tabindex="-1">3.23.7 Technical Support and Discussion <a class="header-anchor" href="#_3-23-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.23.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',54)])])}const P=i(m,[["render",u]]);export{k as __pageData,P as default};
